"""``taskman`` — a tiny, pure-Python, stdlib-only task manager.

The public surface is the :class:`TaskManager` class.  It models a small set
of tasks with:

* an autogenerated unique id per task,
* a priority in the inclusive range ``1..5`` (5 is most important),
* free-form string tags,
* dependency edges to other tasks (used to compute what is *ready*),
* an optional ISO-8601 due timestamp,
* a three-state lifecycle: ``todo`` -> ``doing`` -> ``done``.

Everything is intentionally in-memory and serialised to/from plain JSON so the
package has no third-party dependencies.
"""

from __future__ import annotations

from taskman.manager import TaskManager

__all__ = ["TaskManager"]
